#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Move element from pos to position 'placed'
        // Strategy: first move it to the very end (position n-1), then move from end to 'placed'

        // Step 1: bring element at 'pos' to position n-1
        if(pos != n-1){
            // Use x = pos+1, y = n-1-pos. Then element at pos is last of prefix.
            // After op: [suffix][middle][prefix], prefix=[0..pos], element at pos goes to end of new array at position n-1? 
            // No: prefix is [0..x-1]=[0..pos], goes to end. Element at pos (index pos = x-1) goes to position n-1. Yes!
            int x = pos+1, y = n-1-pos;
            // need x+y < n: (pos+1)+(n-1-pos) = n, not < n!
            // So we need to adjust. Use y = n-2-pos instead (one less), if y>0 i.e. pos < n-2
            if(pos < n-2){
                x = pos+1; y = n-2-pos;
                // x+y = pos+1+n-2-pos = n-1 < n. Good.
                ops.push_back({x,y});
                apply(p, x, y);
                // element was at pos=x-1, now at end of prefix which is at position n-1... 
                // Actually prefix [0..pos] goes to positions [n-x..n-1]=[n-pos-1..n-1]. Element at pos goes to n-1.
                // But wait, there's a middle element at index n-y-1 = pos+2-1 = pos+1... let me just find it
            } else {
                // pos == n-2, use x=1, y=1 to rotate, then retry
                ops.push_back({1,1});
                apply(p,1,1);
            }
            // Re-find
            for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos==placed) continue;
            if(pos!=n-1){
                // Try once more
                if(pos+1 + (n-2-pos) < n && pos < n-2 && n-2-pos > 0){
                    ops.push_back({pos+1, n-2-pos});
                    apply(p, pos+1, n-2-pos);
                    for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
            }
        }
        if(pos==placed) continue;
        if(pos==n-1 && placed+2 < n){
            // element at n-1, want at 'placed'. Use x=placed, y=1 if placed>0
            // After: [last_elem][middle][first_placed_elems]. Element goes to position 0... we want 'placed'
            // Use x=placed+1, y=1: suffix=[n-1], middle=[placed+1..n-2], prefix=[0..placed]
            // Result: [p[n-1]][p[placed+1]..p[n-2]][p[0]..p[placed]]
            // Element at n-1 goes to position 0. But we want position 'placed'. Hmm.
            // Actually if placed==0, position 0 is correct!
            if(placed==0){
                ops.push_back({1,1});
                apply(p,1,1);
            } else {
                // x=placed, y=1: result=[p[n-1]][p[placed]..p[n-2]][p[0]..p[placed-1]]
                // element goes to pos 0, not placed. 
                // Better: think of it differently. We want sorted[0..placed-1] to stay, and p[n-1] to go to placed.
                // x=placed, y=1: [0..placed-1] swapped with [n-1]. sorted prefix goes to end. Bad.
                // Instead use two ops or different params
                // Actually: x=placed+1, y=1 puts element at position 0 and shifts placed+1..n-2 right, prefix 0..placed goes to end
                // Not ideal. Let me just do: x=1, y=n-1-placed => brings suffix to front
                int yy = n-1-placed;
                if(1 + yy < n && yy > 0){
                    ops.push_back({1, yy});
                    apply(p, 1, yy);
                    for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                    if(pos!=placed && pos < n && placed+2<n){
                        // one more attempt
                    }
                }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
